theorem atanh_arg_bounds {m : ℚ} (hlo : 1/2 ≤ m) (hhi : m ≤ 2) :
    let y := (m - 1) / (m + 1)
    (-1)/3 ≤ y ∧ y ≤ 1/3

lemma derivWithin_Icc_left_eq_deriv {f : ℝ → ℝ} {c x : ℝ}
    (hcx : c < x) (hf : DifferentiableAt ℝ f c) :
    derivWithin f (Set.Icc c x) c = deriv f c

lemma derivWithin_Icc_right_eq_deriv {f : ℝ → ℝ} {c x : ℝ}
    (hcx : c < x) (hf : DifferentiableAt ℝ f x) :
    derivWithin f (Set.Icc c x) x = deriv f x

lemma iteratedDerivWithin_Icc_interior_eq {f : ℝ → ℝ} {a b : ℝ} {x : ℝ} {n : ℕ}
    (_hab : a < b) (hx : x ∈ Set.Ioo a b) :
    iteratedDerivWithin n f (Set.Icc a b) x = iteratedDeriv n f x

lemma iteratedDerivWithin_Icc_left_eq_iteratedDeriv {f : ℝ → ℝ} {c x : ℝ} {n : ℕ}
    (hcx : c < x) (hf : ContDiff ℝ n f) :
    iteratedDerivWithin n f (Set.Icc c x) c = iteratedDeriv n f c

lemma iteratedDeriv_reflect_of_contDiffOn {f : ℝ → ℝ} {c : ℝ} {n : ℕ} {U : Set ℝ}
    (hU_open : IsOpen U) (hf : ContDiffOn ℝ n f U) (t : ℝ) (ht : 2 * c - t ∈ U) :
    iteratedDeriv n (fun s => f (2 * c - s)) t = (-1 : ℝ) ^ n * iteratedDeriv n f (2 * c - t)

theorem sound {R : Type*} [CommMonoidWithZero R] {f g : ArithmeticFunction R}
    (cert : LocalPrimePowerCert f g) :
    f = g

theorem mem_add {a b : AffineForm} {eps : NoiseAssignment} {va vb : ℝ}
    (ha : mem_affine a eps va) (hb : mem_affine b eps vb) :
    mem_affine (add a b) eps (va + vb)

theorem mem_scale (q : ℚ) {a : AffineForm} {eps : NoiseAssignment} {v : ℝ}
    (hmem : mem_affine a eps v) :
    mem_affine (scale q a) eps ((q : ℝ) * v)

theorem mem_sub {a b : AffineForm} {eps : NoiseAssignment} {va vb : ℝ}
    (ha : mem_affine a eps va) (hb : mem_affine b eps vb) :
    mem_affine (sub a b) eps (va - vb)

theorem mem_invInterval {x : ℝ} {I : IntervalRat}
    (hx : x ∈ I) (hbnd : |x⁻¹| ≤ invWideBound) :
    x⁻¹ ∈ invInterval I

theorem mem_invInterval_neg {x : ℝ} {I : IntervalRat}
    (hx : x ∈ I) (hneg : I.hi < 0) :
    x⁻¹ ∈ invInterval I

theorem mem_invInterval_nonzero {x : ℝ} {I : IntervalRat}
    (hx : x ∈ I) (hnonzero : I.lo > 0 ∨ I.hi < 0) :
    x⁻¹ ∈ invInterval I

theorem mem_invInterval_pos {x : ℝ} {I : IntervalRat}
    (hx : x ∈ I) (hpos : I.lo > 0) :
    x⁻¹ ∈ invInterval I

theorem BoxEnvMem.get {rho : Nat → ℝ} {box : List IntervalRat}
    (h : BoxEnvMem rho box) (i : Nat) (hi : i < box.length) :
    rho i ∈ box[i]'hi

theorem evalInterval1_correct {e : Expr} {interval : IntervalRat}
    {options : EvalOptions} {outcome : IntervalOutcome}
    (hsuccess : evalInterval1 e interval options = .ok outcome)
    {x : ℝ} (hx : x ∈ interval) :
    Expr.eval (pointEnv1 x) e ∈ outcome.interval

theorem evalInterval_correct {e : Expr} {box : List IntervalRat}
    {options : EvalOptions} {outcome : IntervalOutcome}
    (hsuccess : evalInterval e box options = .ok outcome)
    {rho : Nat → ℝ} (hrho : BoxEnvMem rho box) :
    Expr.eval rho e ∈ outcome.interval

theorem evalGradient_correct {e : Expr} {box : List IntervalRat}
    {options : ADOptions} {outcome : GradientOutcome}
    (hsuccess : evalGradient e box options = .ok outcome)
    {rho : Nat → ℝ} (hrho : BoxEnvMem rho box) :
    List.Forall₂ (fun i dI => deriv (Expr.evalAlong e rho i) (rho i) ∈ dI)
      (List.range box.length) outcome.gradient

theorem evalWithDerivative_correct {e : Expr} {box : List IntervalRat} {idx : Nat}
    {options : ADOptions} {outcome : DerivativeOutcome}
    (hsuccess : evalWithDerivative e box idx options = .ok outcome)
    {rho : Nat → ℝ} (hrho : BoxEnvMem rho box) {x : ℝ}
    (hx : x ∈ intervalEnvOfList box idx) :
    Expr.eval rho e ∈ outcome.value ∧
      deriv (Expr.evalAlong e rho idx) x ∈ outcome.derivative

theorem eval_correct {e : Expr} {box : List IntervalRat}
    {precision : PrecisionOptions} {result : AffineForm}
    (hsuccess : eval e box precision = .ok result) {rho : Nat → ℝ}
    (hrho : BoxEnvMem rho box) : Expr.eval rho e ∈ result.toInterval

theorem eval_correct {e : Expr} {box : List IntervalRat}
    {precision : PrecisionOptions} {result : IntervalDyadic}
    (hsuccess : eval e box precision = .ok result) {rho : Nat → ℝ}
    (hrho : BoxEnvMem rho box) : Expr.eval rho e ∈ result

theorem eval_correct {e : Expr} {box : List IntervalRat} {result : IntervalRat}
    (hsuccess : eval e box = .ok result) {rho : Nat → ℝ}
    (hrho : BoxEnvMem rho box) : Expr.eval rho e ∈ result

theorem verifyBounds {e : Expr} {interval : IntervalRat} {lower upper : ℚ}
    {precision : PrecisionOptions}
    (hcheck : checkBounds e interval lower upper precision = true) :
    ∀ x ∈ interval,
      lower ≤ Expr.eval (fun _ => x) e ∧ Expr.eval (fun _ => x) e ≤ upper

theorem verifyLowerBound {e : Expr} {interval : IntervalRat} {bound : ℚ}
    {precision : PrecisionOptions}
    (hcheck : checkLowerBound e interval bound precision = true) :
    ∀ x ∈ interval, bound ≤ Expr.eval (fun _ => x) e

theorem verifyLowerBoundBox {e : Expr} {box : List IntervalRat} {bound : ℚ}
    {options : EvalOptions} {outcome : BoundCheckOutcome}
    (hcheck : checkLowerBoundBox e box bound options = .ok outcome)
    (hverified : outcome.verified = true) :
    ∀ rho, BoxEnvMem rho box → bound ≤ Expr.eval rho e

theorem verifyUpperBound {e : Expr} {interval : IntervalRat} {bound : ℚ}
    {precision : PrecisionOptions}
    (hcheck : checkUpperBound e interval bound precision = true) :
    ∀ x ∈ interval, Expr.eval (fun _ => x) e ≤ bound

theorem verifyUpperBoundBox {e : Expr} {box : List IntervalRat} {bound : ℚ}
    {options : EvalOptions} {outcome : BoundCheckOutcome}
    (hcheck : checkUpperBoundBox e box bound options = .ok outcome)
    (hverified : outcome.verified = true) :
    ∀ rho, BoxEnvMem rho box → Expr.eval rho e ≤ bound

theorem shift_identity' {F : ℂ → ℂ} {σ₀ σ₁ : ℝ}
    (C : ContourShiftCert F σ₀ σ₁) :
    C.leftValue = C.rightValue + (2 * Real.pi * I) * C.residueSum

theorem toVanishCert {F : ℂ → ℂ} {σ₀ σ₁ : ℝ} {T : ℕ → ℝ}
    (B : HorizontalBoundCert F σ₀ σ₁ T) :
    HorizontalVanishCert F σ₀ σ₁ T

theorem nonreal_heat_zero_of_xiHeat_zero {t : ℝ} {s : ℂ}
    (hz : xiHeat t s = 0) (hs : (1/2 : ℝ) < s.re) :
    H t (heatCoordinate s) = 0 ∧ (heatCoordinate s).im ≠ 0

theorem evalSet_of_remainder (tm : TaylorModel) (x : ℝ) {r : ℝ}
    (hr : r ∈ tm.remainder) :
    tm.evalPoly x + r ∈ tm.evalSet x

theorem neg_evalSet_of_mem {tm : TaylorModel} {x r : ℝ}
    (hr : r ∈ tm.remainder) :
    -(tm.evalPoly x + r) ∈ (neg tm).evalSet x

theorem remainder_four_terms_mem {v_tail v_p1r2 v_p2r1 v_r1r2 : ℝ}
    {I_tail I_p1r2 I_p2r1 I_r1r2 : IntervalRat}
    (htail : v_tail ∈ I_tail) (hp1r2 : v_p1r2 ∈ I_p1r2)
    (hp2r1 : v_p2r1 ∈ I_p2r1) (hr1r2 : v_r1r2 ∈ I_r1r2) :
    v_tail + v_p1r2 + v_p2r1 + v_r1r2 ∈
      IntervalRat.add I_tail (IntervalRat.add I_p1r2 (IntervalRat.add I_p2r1 I_r1r2))

theorem monomial_bernstein_expansion (n j : ℕ) (hjn : j ≤ n) (t : ℝ) :
    t ^ j = (Finset.range (n + 1)).sum (fun k =>
      if j ≤ k then (Nat.choose (n - j) (k - j) : ℝ) * t ^ k * (1 - t) ^ (n - k)
      else 0)

theorem exists_mem_closedCell (root : IntervalDyadic) (depth : Nat) {x : ℝ}
    (hx : x ∈ root) :
    ∃ index : Fin (2 ^ depth), x ∈ closedCell root depth index

theorem exists_unique_owner (root : IntervalDyadic) (depth : Nat) {x : ℝ}
    (hx : x ∈ root) :
    ∃! index : Fin (2 ^ depth), Owns root depth index x

theorem last_owns_of_mem {root : IntervalDyadic} {depth : Nat} {x : ℝ}
    (hx : x ∈ closedCell root depth (lastIndex depth)) :
    Owns root depth (lastIndex depth) x

theorem mem_ownerSet_of_mem_root (root : IntervalDyadic) (depth : Nat) {x : ℝ}
    (hx : x ∈ root) :
    ∃ index : Fin (2 ^ depth), x ∈ ownerSet root depth index

theorem ownerSet_disjoint {root : IntervalDyadic} {depth : Nat}
    {i j : Fin (2 ^ depth)} (hne : i ≠ j) :
    Disjoint (ownerSet root depth i) (ownerSet root depth j)

theorem mem_cell_of_mem_succ {root : IntervalDyadic} {bits : InfiniteDyadicPath}
    {depth : Nat} {x : ℝ} (hx : x ∈ bits.cell root (depth + 1)) :
    x ∈ bits.cell root depth

theorem mem_centered {v_real : List ℝ} {v : AffineVector} {eps : AffineForm.NoiseAssignment}
    (hvalid : AffineForm.validNoise eps)
    (hmem : mem v_real v eps) :
    let μ := v_real.sum / v_real.length
    let centered_real := v_real.map (· - μ)
    mem centered_real (centered v) eps

theorem quadraticZeroSet_ncard_eq_one_of_discrim_eq_zero {a b c : ℝ}
    (ha : a ≠ 0) (hΔ : discrim a b c = 0) :
    (quadraticZeroSet a b c).ncard = 1

theorem quadraticZeroSet_ncard_eq_two_of_discrim_pos {a b c : ℝ}
    (ha : a ≠ 0) (hΔ : 0 < discrim a b c) :
    (quadraticZeroSet a b c).ncard = 2

theorem three_mem_exhaust_ncard {α : Type*} {S : Set α} {x₁ x₂ x₃ : α}
    (hcard : S.ncard = 3) (h₁ : x₁ ∈ S) (h₂ : x₂ ∈ S) (h₃ : x₃ ∈ S)
    (h₁₂ : x₁ ≠ x₂) (h₁₃ : x₁ ≠ x₃) (h₂₃ : x₂ ≠ x₃) :
    S = {x₁, x₂, x₃}

theorem QCubic.roots_eq_three_of_mem (P : QCubic) (ha : P.a ≠ 0) {x y z : ℝ}
    (hx : x ∈ cubicZeroSet P.toReal) (hy : y ∈ cubicZeroSet P.toReal)
    (hz : z ∈ cubicZeroSet P.toReal)
    (hxy : x ≠ y) (hxz : x ≠ z) (hyz : y ≠ z) :
    P.toReal.roots = {x, y, z}

theorem QCubic.separationMeshCheck_sound_of_distinct_roots
    (P : QCubic) {eps : ℚ}
    (hcount : P.threeRootCountCheck = true)
    (hmesh : P.separationMeshCheck eps = true) {x y : ℝ}
    (hx : x ∈ cubicZeroSet P.toReal) (hy : y ∈ cubicZeroSet P.toReal)
    (hxy : x ≠ y) : (eps : ℝ) < |x - y|

theorem aeval_le_of_bernsteinCheck {p : QPoly} {c : ℚ} {I : IntervalRat} {depth : Nat}
    (h : bernsteinCheck .upper p c I depth = true) :
    ∀ x ∈ I, Polynomial.aeval x p.toPoly ≤ (c : ℝ)

theorem aeval_lt_of_bernsteinCheck {p : QPoly} {c : ℚ} {I : IntervalRat} {depth : Nat}
    (h : bernsteinCheck .strictUpper p c I depth = true) :
    ∀ x ∈ I, Polynomial.aeval x p.toPoly < (c : ℝ)

theorem bernsteinCheck_sound {cmp : Cmp} {p : QPoly} {c : ℚ} {I : IntervalRat}
    {depth : Nat} (h : bernsteinCheck cmp p c I depth = true) :
    ∀ x ∈ I, cmp.holds c (Polynomial.aeval x p.toPoly)

theorem le_aeval_of_bernsteinCheck {p : QPoly} {c : ℚ} {I : IntervalRat} {depth : Nat}
    (h : bernsteinCheck .lower p c I depth = true) :
    ∀ x ∈ I, (c : ℝ) ≤ Polynomial.aeval x p.toPoly

theorem lt_aeval_of_bernsteinCheck {p : QPoly} {c : ℚ} {I : IntervalRat} {depth : Nat}
    (h : bernsteinCheck .strictLower p c I depth = true) :
    ∀ x ∈ I, (c : ℝ) < Polynomial.aeval x p.toPoly

theorem mem_atanhIntervalRefined {x : ℝ} {I : IntervalRat}
    (hx : x ∈ I) (hlo : -1 < I.lo) (hhi : I.hi < 1) :
    Real.atanh x ∈ atanhIntervalRefined I

theorem mem_scalarMulInterval {w : ℚ} {x : ℝ} {I : IntervalDyadic}
    (hx : x ∈ I) (prec : Int) (hprec : prec ≤ 0 := by norm_num) :
    (w : ℝ) * x ∈ scalarMulInterval w I prec

theorem descend_widestDecision?_eq {B : Box} {upper : Bool} {decision : BoxDecision B.length}
    (hdecision : widestDecision? B upper = some decision) :
    descend B decision = if upper then B.splitWidest.2 else B.splitWidest.1

theorem checkExpComputableLoPos_spec {I : IntervalRat} {n : Nat}
    (h : checkExpComputableLoPos I n = true) :
    (IntervalRat.expComputable I n).lo > 0

lemma quotient_hi_ge_neg {fc : IntervalRat} {dI : IntervalRat.IntervalRatNonzero}
    (hdI_neg : dI.hi < 0) :
    let Q := IntervalRat.mul fc (IntervalRat.invNonzero dI)
    Q.hi ≥ fc.lo / dI.hi

lemma quotient_hi_lower_bound {fc : IntervalRat} {dI : IntervalRat.IntervalRatNonzero}
    (hdI_pos : 0 < dI.lo) :
    let Q := IntervalRat.mul fc (IntervalRat.invNonzero dI)
    Q.hi ≥ fc.hi / dI.lo

lemma quotient_lo_le_neg {fc : IntervalRat} {dI : IntervalRat.IntervalRatNonzero}
    (hdI_neg : dI.hi < 0) :
    let Q := IntervalRat.mul fc (IntervalRat.invNonzero dI)
    Q.lo ≤ fc.hi / dI.hi

lemma quotient_lo_upper_bound {fc : IntervalRat} {dI : IntervalRat.IntervalRatNonzero}
    (hdI_pos : 0 < dI.lo) :
    let Q := IntervalRat.mul fc (IntervalRat.invNonzero dI)
    Q.lo ≤ fc.lo / dI.lo

theorem abs_sub_center_le_coordinateRadius {n : Nat} {X : Fin n → IntervalRat}
    {m : Fin n → ℚ} {x : Fin n → ℝ} (hx : FinBoxMem x X) (i : Fin n) :
    |x i - (m i : ℝ)| ≤ coordinateRadius X m i

theorem norm_sub_center_le_boxRadius {n : Nat} {X : Fin n → IntervalRat}
    {m : Fin n → ℚ} {x : Fin n → ℝ} (hx : FinBoxMem x X) :
    ‖x - (fun i => (m i : ℝ))‖ ≤ (boxRadius X m : ℝ)

theorem row_checked_of_list_all {checker : Row → Bool} {rows : List Row} {row : Row}
    (hall : rows.all checker = true) (hmem : row ∈ rows) :
    checker row = true

theorem checkEquivalence_dims {teacher student : SequentialNet}
    {domain : IntervalVector} {eps : ℚ} {prec : Int}
    (h : checkEquivalence teacher student domain eps prec = true) :
    (SequentialNet.forwardInterval teacher domain prec).length =
    (SequentialNet.forwardInterval student domain prec).length

theorem intervalBoundedBy_spec {x : ℝ} {I : IntervalDyadic} {eps : ℚ}
    (hx : x ∈ I) (hcheck : intervalBoundedBy I eps = true) :
    |x| ≤ (eps : ℝ)

theorem mem_add {x y : Fin n → ℝ} {a b : IntervalArray n}
    (hx : x ∈ a) (hy : y ∈ b) :
    (fun i => x i + y i) ∈ add a b

theorem mem_sub {x y : Fin n → ℝ} {a b : IntervalArray n}
