theorem mem_geluInterval {x : ℝ} {I : IntervalDyadic}
    (hx : x ∈ I) (prec : Int) (hprec : prec ≤ 0 := by norm_num) :
    Real.gelu x ∈ geluInterval I prec

theorem mem_geluIntervalRat {x : ℝ} {I : IntervalRat}
    (hx : x ∈ I) :
    Real.gelu x ∈ geluIntervalRat I

theorem mem_map_intervals {f : ℝ → ℝ} {g : IntervalDyadic → IntervalDyadic}
    {xs : List ℝ} {Is : IntervalVector}
    (hlen : xs.length = Is.length)
    (hmem : ∀ i, i < xs.length → xs[i]! ∈ Is[i]!)
    (hf : ∀ x I, x ∈ I → f x ∈ g I) :
    ∀ i, i < xs.length → (xs.map f)[i]! ∈ (Is.map g)[i]!

theorem F_second_difference_nonneg {S : Finset Nat} {c d : Nat}
    (hc : c ∈ S) (hd : d ∈ S) (hcd : c ≠ d) :
    0 ≤ F S - F (S.erase c) - F (S.erase d) + F ((S.erase c).erase d)

theorem one_sub_mul_sum_pow_le {A : Finset Nat} {m : Nat}
    (hm : ∀ q ∈ A, m ≤ q) {u : ℝ} (hu : u ∈ Set.Icc (0 : ℝ) 1) :
    (1 - u) * ∑ q ∈ A, u ^ q ≤ u ^ m

theorem checkDomainValidAffine_correct {e : Expr} {ρ : AffineEnv} {cfg : AffineConfig}
    (h : checkDomainValidAffine e ρ cfg = true) :
    evalDomainValidAffine e ρ cfg
